// Command gen writes the golden backup artifacts of internal/restore/testdata/compat:
// a tiny fake mongodump archive stored in every layout MongoRescue has produced
// since v0.1.0 (plain, gzip, age over plain, age over gzip, with X25519 and with a
// passphrase), under storage keys following the backup engine's naming scheme,
// together with the backup records the metadata store kept for them.
//
// Run it from internal/restore with "go generate" (see compat_fixtures_test.go).
// The X25519 identity in TEST-ONLY-age-identity.txt is reused when present, so
// regenerating only changes the (randomised) age ciphertexts.
//
// TEST ONLY: the identity and passphrase used here are public. Never use them for
// real backups.
package main

import (
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/yigitcittan/mongorescue/internal/encryption"
	"github.com/yigitcittan/mongorescue/internal/models"
)

// Passphrase is the TEST ONLY passphrase of the scrypt fixture.
const Passphrase = "TEST ONLY passphrase - never use for real backups"

// scryptWorkFactor keeps the scrypt fixture fast to decrypt in tests.
const scryptWorkFactor = 10

const identityFile = "TEST-ONLY-age-identity.txt"

// fixture describes one golden artifact in manifest.json.
type fixture struct {
	// Name identifies the layout.
	Name string `json:"name"`
	// WantGzip reports whether mongorestore must be started with --gzip.
	WantGzip bool `json:"want_gzip"`
	// WantStdin is the file (relative to the compat directory) whose bytes mongorestore
	// must receive on stdin.
	WantStdin string `json:"want_stdin"`
	// Record is the backup record as the metadata store kept it.
	Record models.BackupRecord `json:"record"`
}

type manifest struct {
	Comment  string    `json:"comment"`
	Fixtures []fixture `json:"fixtures"`
}

// fakeArchive is a stand-in for mongodump --archive output: the archive magic
// number (0x8199e26d, little endian) followed by readable filler. It is not a
// valid archive; the fake mongorestore of the tests only captures it.
func fakeArchive() []byte {
	var b bytes.Buffer
	b.Write([]byte{0x6d, 0xe2, 0x99, 0x81})
	b.WriteString("\x00fake mongodump archive of db shop (collections: orders, customers); TEST ONLY, not real BSON\n")
	for i := range 64 {
		fmt.Fprintf(&b, "orders document %02d {\"_id\": %d, \"total\": %d.%02d}\n", i, i, i*3, i%100)
	}
	return b.Bytes()
}

func main() {
	dir := flag.String("dir", "testdata/compat", "output directory")
	flag.Parse()
	if err := run(*dir); err != nil {
		log.Fatal(err)
	}
}

func run(dir string) error {
	_, recipient, err := loadOrCreateIdentity(filepath.Join(dir, identityFile))
	if err != nil {
		return err
	}
	x25519, err := encryption.NewX25519Encryptor([]string{recipient})
	if err != nil {
		return err
	}
	scrypt, err := encryption.NewScryptEncryptor(Passphrase, scryptWorkFactor)
	if err != nil {
		return err
	}

	archive := fakeArchive()
	var gz bytes.Buffer
	zw := gzip.NewWriter(&gz) // no name or mod time: deterministic output
	if _, err = zw.Write(archive); err != nil {
		return err
	}
	if err = zw.Close(); err != nil {
		return err
	}

	if err = os.RemoveAll(filepath.Join(dir, "store")); err != nil {
		return err
	}
	if err = write(filepath.Join(dir, "fake-mongodump.archive"), archive); err != nil {
		return err
	}

	start := time.Date(2026, 9, 25, 12, 0, 0, 0, time.UTC)
	key := func(minute int, suffix, ext string) (id, storageKey string) {
		at := start.Add(time.Duration(minute) * time.Minute)
		id = fmt.Sprintf("bkp_shop_%s_%s", at.Format("20060102_150405"), suffix)
		return id, fmt.Sprintf("shop/%s/%s.%s", at.Format("2006/01"), id, ext)
	}
	_, plainKey := key(0, "a1b2c3", "archive")
	_, gzipKey := key(1, "d4e5f6", "archive.gz")

	layouts := []struct {
		name, suffix, ext string
		stored            func() ([]byte, error)
		gzip              bool
		stdinKey          string
		mode              encryption.Mode
	}{
		{"plain", "a1b2c3", "archive", func() ([]byte, error) { return archive, nil }, false, plainKey, ""},
		{"gzip", "d4e5f6", "archive.gz", func() ([]byte, error) { return gz.Bytes(), nil }, true, gzipKey, ""},
		{"age x25519 over gzip", "0a1b2c", "archive.gz.age", func() ([]byte, error) { return seal(x25519, gz.Bytes()) }, true, gzipKey, encryption.ModeX25519},
		{"age x25519 over plain", "3d4e5f", "archive.age", func() ([]byte, error) { return seal(x25519, archive) }, false, plainKey, encryption.ModeX25519},
		{"age scrypt over gzip", "6a7b8c", "archive.gz.age", func() ([]byte, error) { return seal(scrypt, gz.Bytes()) }, true, gzipKey, encryption.ModeScrypt},
	}

	m := manifest{Comment: "Golden backup artifacts generated by gen/main.go (go generate in internal/restore). TEST ONLY: " +
		"the age identity in " + identityFile + " and the passphrase in gen/main.go are public; never use them for real backups."}
	for i, l := range layouts {
		stored, err := l.stored()
		if err != nil {
			return fmt.Errorf("%s: %w", l.name, err)
		}
		id, storageKey := key(i, l.suffix, l.ext)
		if err = write(filepath.Join(dir, "store", filepath.FromSlash(storageKey)), stored); err != nil {
			return err
		}
		sum := sha256.Sum256(stored)
		at := start.Add(time.Duration(i) * time.Minute)
		done := at.Add(7 * time.Second)
		m.Fixtures = append(m.Fixtures, fixture{
			Name: l.name, WantGzip: l.gzip, WantStdin: "store/" + l.stdinKey,
			Record: models.BackupRecord{
				ID: id, Trigger: models.TriggerManual, Database: "shop", Status: models.StatusCompleted,
				StorageType: models.StorageLocal, StorageKey: storageKey, SizeBytes: int64(len(stored)),
				SHA256: hex.EncodeToString(sum[:]), Encrypted: l.mode != "", EncryptionMode: string(l.mode),
				StartedAt: at, CompletedAt: &done, DurationSeconds: 7,
			},
		})
	}
	raw, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}
	return write(filepath.Join(dir, "manifest.json"), append(raw, '\n'))
}

func seal(enc *encryption.Encryptor, plain []byte) ([]byte, error) {
	var buf bytes.Buffer
	w, err := enc.Encrypt(&buf)
	if err != nil {
		return nil, err
	}
	if _, err = w.Write(plain); err != nil {
		return nil, err
	}
	if err = w.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// loadOrCreateIdentity reads the TEST ONLY identity file, creating it on first run.
func loadOrCreateIdentity(path string) (identity, recipient string, err error) {
	content, err := os.ReadFile(path)
	if errors.Is(err, fs.ErrNotExist) {
		if identity, recipient, err = encryption.GenerateX25519(); err != nil {
			return "", "", err
		}
		file := "# TEST ONLY - NEVER USE FOR REAL BACKUPS.\n" +
			"# This age identity is public: it decrypts the golden fixtures in this directory.\n" +
			"# public key: " + recipient + "\n" + identity + "\n"
		return identity, recipient, write(path, []byte(file))
	}
	if err != nil {
		return "", "", err
	}
	recipients, err := encryption.IdentityRecipients(string(content))
	if err != nil || len(recipients) != 1 {
		return "", "", fmt.Errorf("%s: want exactly one identity: %v", path, err)
	}
	for _, line := range strings.Split(string(content), "\n") {
		if strings.HasPrefix(line, "AGE-SECRET-KEY-1") {
			identity = line
		}
	}
	return identity, recipients[0], nil
}

func write(path string, data []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
		return err
	}
	return os.WriteFile(path, data, 0o600)
}
